import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"第六阶段 · 多设备与长期运行","description":"让同一套任务、记忆和授权在多台设备上长期安全使用。","frontmatter":{"title":"第六阶段 · 多设备与长期运行","description":"让同一套任务、记忆和授权在多台设备上长期安全使用。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6.md","filePath":"delivery/stage-6.md","lastUpdated":1794305977000}'),i={name:"delivery/stage-6.md"};function o(d,t,s,h,n,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="第六阶段-·-多设备与长期运行" tabindex="-1">第六阶段 · 多设备与长期运行 <a class="header-anchor" href="#第六阶段-·-多设备与长期运行" aria-label="Permalink to &quot;第六阶段 · 多设备与长期运行&quot;">​</a></h1><p>当前实现、已验证范围和明确留空项见<a href="/hearth-os/delivery/status.html">阶段二至六交付状态</a>。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现代码闭环：</strong> 增量事件同步与冲突选择、任务租约与 epoch fencing、设备撤销与令牌轮换、kill switch、加密备份恢复、健康检查、维护和脱敏诊断；连接运行时分离 transport、subscription、dataFreshness 与 executionOwnership，并提供 generation 隔离、离线 outbox 和缓存投影。</li><li><strong>仍未完成：</strong> 真实远程节点与手机接入、真实断网重连与跨节点 outbox 对账、真实双设备切换、设备丢失演练、完整迁移、数周连续运行和 v1.0 发布验收。逐项证据见<a href="/hearth-os/delivery/status.html">阶段二至六交付状态</a>。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第六阶段把单机产品扩展为可以长期运行、在多台设备之间保持一致、可备份、可迁移、可撤销的个人 Agent OS。多设备不是复制多个 Agent，而是同一套任务、记忆和授权在不同设备上继续使用。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-6/6-1.html">6.1 多设备同步与切换</a></td><td>同一套任务和产物在不同设备上保持一致。</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/6-2.html">6.2 设备撤销与安全迁移</a></td><td>设备丢失后可立即失效，更换设备时数据完整转移。</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/6-3.html">6.3 备份、恢复与升级</a></td><td>换机器、换版本或误操作都不丢任务、产物和记忆。</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/6-4.html">6.4 长期运行与 v1.0 验收</a></td><td>长期稳定运行，完成整体验收后发布 v1.0。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先让多台设备看到一致的任务和产物。</li><li>再处理断网、设备切换和能力分配。</li><li>然后补齐设备撤销、备份、恢复和升级。</li><li>最后做长期运行和完整验收，形成 v1.0。</li></ol>',10)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
